alt:
package main

import (
	"errors"
	"fmt"
)

var errZero = errors.New("division by zero")

func Divide(a, b float64) (float64, error) {
	if b != 0 {
		return a / b, nil
	}
	return 0, errZero
}

func main() {
	res, err := Divide(10, 4)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(res)
}
